// Moves the CMake build staging directory to a short path on Windows.
//
// The React Native codegen for MapLibre nests deep folders under
// android/app/.cxx. From a long checkout path (an Orca worktree, for example)
// ninja then exceeds the Windows MAX_PATH limit and fails with
// `mkdir(...MapLibreReactNativeSpec...): No such file or directory`.
// A `subst` drive does not help: Expo and Gradle resolve it back to the long
// path. Pointing the staging directory at C:/gx keeps every path short.
//
// android/ is generated by `expo prebuild`, so the fix has to live here.

const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// with-short-cxx-path';
const ANCHOR = 'ndkVersion rootProject.ext.ndkVersion';

const BLOCK = `
    ${MARKER}
    if (System.getProperty('os.name').toLowerCase().contains('windows')) {
        externalNativeBuild {
            cmake {
                // One folder per checkout so worktrees never share a CMake cache.
                buildStagingDirectory "C:/gx/" + Integer.toHexString(rootDir.absolutePath.hashCode())
            }
        }
    }`;

module.exports = function withShortCxxPath(config) {
  return withAppBuildGradle(config, (mod) => {
    const gradle = mod.modResults.contents;
    if (gradle.includes(MARKER)) {
      return mod;
    }
    if (!gradle.includes(ANCHOR)) {
      throw new Error(
        `with-short-cxx-path: anchor "${ANCHOR}" not found in app/build.gradle`,
      );
    }
    mod.modResults.contents = gradle.replace(ANCHOR, `${ANCHOR}\n${BLOCK}`);
    return mod;
  });
};
